impl Document {
    pub(crate) fn compare_external_triggering_point_ident(
        &self,
        other: &Document,
        a: &ExternalTriggeringPointIdent,
        b: &ExternalTriggeringPointIdent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ident_caption(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_ident_caption(
        &self,
        other: &Document,
        a: &IdentCaption,
        b: &IdentCaption,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_mode_access_point_ident(
        &self,
        other: &Document,
        a: &ModeAccessPointIdent,
        b: &ModeAccessPointIdent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ident_caption(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_rapid_prototyping_scenario(
        &self,
        other: &Document,
        a: &RapidPrototypingScenario,
        b: &RapidPrototypingScenario,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_rpt_executable_entity_properties(
        &self,
        _other: &Document,
        a: &RptExecutableEntityProperties,
        b: &RptExecutableEntityProperties,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_max_rpt_event_id() != b.get_max_rpt_event_id() {
            return Err(format!("{path}: MAX_RPT_EVENT_ID mismatch"));
        }
        if a.get_min_rpt_event_id() != b.get_min_rpt_event_id() {
            return Err(format!("{path}: MIN_RPT_EVENT_ID mismatch"));
        }
        if a.get_rpt_execution_control() != b.get_rpt_execution_control() {
            return Err(format!("{path}: RPT_EXECUTION_CONTROL mismatch"));
        }
        if a.get_rpt_service_point() != b.get_rpt_service_point() {
            return Err(format!("{path}: RPT_SERVICE_POINT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_hook(
        &self,
        _other: &Document,
        a: &RptHook,
        b: &RptHook,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_rpt_impl_policy(
        &self,
        _other: &Document,
        a: &RptImplPolicy,
        b: &RptImplPolicy,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_rpt_enabler_impl_type() != b.get_rpt_enabler_impl_type() {
            return Err(format!("{path}: RPT_ENABLER_IMPL_TYPE mismatch"));
        }
        if a.get_rpt_preparation_level() != b.get_rpt_preparation_level() {
            return Err(format!("{path}: RPT_PREPARATION_LEVEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_profile(
        &self,
        _other: &Document,
        a: &RptProfile,
        b: &RptProfile,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }
}
